"use client";

import { useState } from "react";
import type { Comanda } from "@/types/cocinero";
import ComandaCard from "./comanda-card";
import detalle_comandaData from "@/data/detalle_comanda.json";

const comandasIniciales = detalle_comandaData as Comanda[];

export default function GridComandas() {
  const [comandas, setComandas] = useState<Comanda[]>(comandasIniciales);

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 auto-rows-fr">
      {comandas.map((comanda) => (
        <ComandaCard
          key={comanda.id_comanda}
          comanda={comanda}
          onClick={() => {}}
        />
      ))}
    </div>
  );
}
